async function api(path,options={}){if(demoMode&&path!=='/logout')throw Error('The demo does not access private cloud projects.');const r=await fetch(endpoint+path,{...options,headers:{Authorization:'Bearer '+token,...options.headers},signal:AbortSignal.timeout(90000),cache:'no-store'});if(!r.ok&&r.status!==404){let d={};try{d=await r.json()}catch{}const e=Error(d.error||'Cloudflare could not save. Please retry.');e.status=r.status;throw e}return r}
