async function media(value,raw=false,scope=projectId){const marker=raw?'data:application/pdf;base64,'+value:value;if(assetCache.has(scope+marker))return assetCache.get(scope+marker);const m=marker.match(/^data:([^;,]*)(;base64)?,([\s\S]*)$/);if(!m)return value;const bytes=m[2]?decode64(m[3]):new TextEncoder().encode(decodeURIComponent(m[3]));if(bytes.byteLength>50*1024*1024)throw Error('Files must be under 50 MB.');const hash=await sha(bytes),key=scope+'/'+hash;if(!uploaded.has(key)){await api(scope==='@studio'?'/studio/assets/'+hash:'/projects/'+key.replace('/','/assets/'),{method:'PUT',headers:{'Content-Type':m[1]||'application/octet-stream'},body:bytes});uploaded.add(key)}const ref={__v2asset:hash,project:scope,mime:m[1]||'application/octet-stream',raw};assetCache.set(scope+marker,ref);return ref}
